def add(a, b=1):
    return a + b
print(add(2), add(2, 5))

class Box:
    def __init__(self, data):
        self.data = data
    def __repr__(self):
        return f"Box({self.data})"

    def __add__(self, other):
        return Box(self.data + other.data)
a = Box(2); b = Box(3)
print(a + b)

    def __call__(self, x):
        return self.data * x
print(a(10))

